(function(){
'use strict';
const configs={
dashboard:{endpoint:'/api/dashboard/executive',kpis:'#dashboardKpis',stamp:'#dashboardGeneratedAt',charts:['#ageStructureChart','#populationMovementChart','#genderStructureChart','#partyMemberChart','#householdTypeChart','#laborStatusChart'],keys:['executiveAges','executiveMovements','executiveGender','executivePolicy','executiveHouseholds','executiveLabor']},
dashboardHouseholds:{endpoint:'/api/dashboard/households',kpis:'#dashboardHouseholdsKpis',stamp:'#dashboardHouseholdsGeneratedAt',charts:['#dashboardHouseholdsChartOne','#dashboardHouseholdsChartTwo','#dashboardHouseholdsChartThree','#dashboardHouseholdsExtra'],keys:['households','gps','profiles','top'],top:'#dashboardHouseholdsExtra'},
dashboardPopulation:{endpoint:'/api/dashboard/population',kpis:'#dashboardPopulationKpis',stamp:'#dashboardPopulationGeneratedAt',charts:['#dashboardPopulationChartOne','#dashboardPopulationChartTwo','#dashboardPopulationChartThree','#dashboardPopulationExtra'],keys:['gender','ages','labor','healthInsurance']},
dashboardBusiness:{endpoint:'/api/dashboard/business',kpis:'#dashboardBusinessKpis',stamp:'#dashboardBusinessGeneratedAt',charts:['#dashboardBusinessChartOne','#dashboardBusinessChartTwo','#dashboardBusinessChartThree'],keys:['types','sectors','scales'],top:'#dashboardBusinessExtra'},
dashboardVehicles:{endpoint:'/api/dashboard/vehicles',kpis:'#dashboardVehiclesKpis',stamp:'#dashboardVehiclesGeneratedAt',charts:['#dashboardVehiclesChartOne','#dashboardVehiclesChartTwo','#dashboardVehiclesChartThree'],keys:['types','households','areas'],top:'#dashboardVehiclesExtra'},
dashboardLivestock:{endpoint:'/api/dashboard/livestock',kpis:'#dashboardLivestockKpis',stamp:'#dashboardLivestockGeneratedAt',charts:['#dashboardLivestockChartOne','#dashboardLivestockChartTwo','#dashboardLivestockChartThree'],keys:['types','scale','areas'],top:'#dashboardLivestockExtra'},
dashboardGis:{endpoint:'/api/dashboard/gis',kpis:'#dashboardGisKpis',stamp:'#dashboardGisGeneratedAt',charts:['#dashboardGisChartOne','#dashboardGisChartTwo','#dashboardGisChartThree'],keys:['gps','business','layers'],top:'#dashboardGisExtra'},
dashboardReports:{endpoint:'/api/dashboard/reports',kpis:'#dashboardReportsKpis',stamp:'#dashboardReportsGeneratedAt',charts:['#dashboardReportsChartOne','#dashboardReportsChartTwo','#dashboardReportsChartThree'],keys:['reports','exports','empty'],top:'#dashboardReportsExtra'}
};
const cache=new Map(),ttl=30000;
const q=(s,r)=> (r||document).querySelector(s);
const qa=(s,r)=> Array.from((r||document).querySelectorAll(s));
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));}
function fmt(v){return new Intl.NumberFormat('vi-VN').format(Number(v||0));}
function empty(msg){return '<div class="dashboard-empty-chart text-muted">'+esc(msg||'Chưa có dữ liệu')+'</div>';}
function params(screen){const host=q('#'+screen+'Screen'),p=new URLSearchParams();if(!host)return p;qa('[data-dashboard-filter]',host).forEach(el=>{const v=String(el.value||'').trim();if(v)p.set(el.dataset.dashboardFilter,v);});return p;}
async function fetchData(url){if(typeof api==='function')return api(url,{cacheTtl:ttl});const token=localStorage.getItem(tenantStorageKey('token'))||window.App?.token||'';const res=await fetch(url,{headers:{Accept:'application/json',Authorization:token?'Bearer '+token:''},cache:'no-store'});const json=await res.json().catch(()=>null);if(!res.ok||!json?.ok)throw new Error(json?.error?.message||'Không tải được Dashboard');return json.data||{};}
function canRead(screen){return typeof window.TenantAppCanAccess!=='function'||window.TenantAppCanAccess(screen,'read');}
function renderDenied(screen){const cfg=configs[screen];if(!cfg)return;const host=q(cfg.kpis)||q('#'+screen+'Screen');if(host)host.innerHTML='<div class="empty-state text-muted py-4 text-center">Bạn không có quyền truy cập</div>';}
async function load(screen,force){const cfg=configs[screen];if(!cfg)return;if(!canRead(screen)){renderDenied(screen);return;}bind(screen);const query=params(screen).toString();const url=cfg.endpoint+(query?'?'+query:'');const hit=cache.get(url);if(!force&&hit&&hit.expires>Date.now()){render(screen,hit.data);return;}try{setBusy(screen,true);const data=await fetchData(url);cache.set(url,{data,expires:Date.now()+ttl});render(screen,data);}catch(e){renderError(cfg,e);}finally{setBusy(screen,false);}}
function setBusy(screen,on){qa('[data-dashboard-refresh]',q('#'+screen+'Screen')||document).forEach(btn=>btn.disabled=!!on);}
function render(screen,data){const cfg=configs[screen];if(!cfg)return;if(screen==='dashboard'){renderExecutiveDashboard(cfg,data);return;}renderKpis(cfg.kpis,kpis(screen,data));stamp(cfg.stamp,data.generatedAt);const charts=data.charts||{};(cfg.charts||[]).forEach((sel,i)=>{const key=cfg.keys[i];if(key==='layers')list(sel,data.layers||[]);else if(key==='reports')list(sel,data.reports||[]);else if(key==='exports')list(sel,data.exports||[]);else if(key==='empty')list(sel,[]);else chart(sel,charts[key]||[]);});if(cfg.top)extra(cfg.top,data);}
function kpis(screen,data){if(data.kpis&&data.kpis.length)return data.kpis;if(screen!=='dashboard')return[];const m=data.metrics||{};return[
{key:'total_households',label:'Tổng số hộ',value:m.total_households,unit:'hộ',icon:'fa-house-chimney',tone:'green'},
{key:'total_citizens',label:'Tổng số nhân khẩu',value:m.total_citizens,unit:'người',icon:'fa-users',tone:'blue'},
{key:'male_count',label:'Nam',value:m.male_count,unit:'người',icon:'fa-mars',tone:'cyan'},
{key:'female_count',label:'Nữ',value:m.female_count,unit:'người',icon:'fa-venus',tone:'pink'},
{key:'party_member_count',label:'Đảng viên',value:m.party_member_count,unit:'người',icon:'fa-star',tone:'orange'},
{key:'children_count',label:'Trẻ em',value:m.children_count,unit:'người',icon:'fa-child-reaching',tone:'blue'},
{key:'elderly_count',label:'Người cao tuổi',value:m.elderly_count,unit:'người',icon:'fa-person-cane',tone:'purple'},
{key:'working_age_count',label:'Lao động',value:m.working_age_count,unit:'người',icon:'fa-briefcase',tone:'green'},
{key:'health_insurance_count',label:'Có BHYT',value:m.health_insurance_count,unit:'người',icon:'fa-notes-medical',tone:'green'},
{key:'temporary_residence_count',label:'Tạm trú',value:m.temporary_residence_count??m.temporary_count,unit:'người',icon:'fa-location-dot',tone:'cyan'},
{key:'temporary_absence_count',label:'Tạm vắng',value:m.temporary_absence_count??m.away_count,unit:'người',icon:'fa-person-walking-arrow-right',tone:'purple'},
{key:'poor_households',label:'Hộ nghèo',value:m.poor_households,unit:'hộ',icon:'fa-hand-holding-heart',tone:'orange'},
{key:'near_poor_households',label:'Hộ cận nghèo',value:m.near_poor_households,unit:'hộ',icon:'fa-hands-holding',tone:'pink'}
];}
function renderExecutiveDashboard(cfg,data){renderKpis(cfg.kpis,executiveKpis(data));stamp(cfg.stamp,data.engine?.generatedAt);renderExecutiveCommand(data);chart('#ageStructureChart',executiveChart(data.insight?.populationStructure,{'0_5':'0-5 tuổi','6_17':'6-17 tuổi','18_59':'18-59 tuổi','60_69':'60-69 tuổi','70_74':'70-74 tuổi','75_plus':'75+ tuổi'}));chart('#populationMovementChart',executiveChart(data.trends?.movements,{birth:'Sinh',death:'Tử',moveIn:'Chuyển đến',moveOut:'Chuyển đi',temporaryResidence:'Tạm trú',temporaryAbsence:'Tạm vắng'}));chart('#genderStructureChart',[{label:'Nam',value:data.overview?.male||0},{label:'Nữ',value:data.overview?.female||0}]);chart('#partyMemberChart',executiveChart(data.policy,{eligibleHealthInsurance:'Đủ điều kiện BHYT',eligibleSocialSupport:'Đủ điều kiện bảo trợ',missingHealthInsurance:'Chưa có BHYT',partyMembers:'Đảng viên'}));chart('#householdTypeChart',executiveChart(data.insight?.households,{elderlyOnlyHouseholds:'Chỉ có người cao tuổi',householdsWithChildren:'Có trẻ em',multiGenerationHouseholds:'Nhiều thế hệ',missingInfoHouseholds:'Thiếu thông tin',dataRiskHouseholds:'Rủi ro dữ liệu'}));chart('#laborStatusChart',executiveChart(data.insight?.labor,{workingAge:'Trong tuổi lao động',outsideWorkingAge:'Ngoài tuổi lao động',employed:'Có việc làm',unemployed:'Chưa có việc làm',pupil:'Học sinh',student:'Sinh viên',retired:'Nghỉ hưu'}));}
function executiveKpis(data){const o=data.overview||{},p=data.policy||{},k=data.kpi||{};return[
{key:'total_households',label:'Tổng hộ',value:o.totalHouseholds,unit:'hộ',icon:'fa-house-chimney',tone:'green'},
{key:'total_citizens',label:'Tổng nhân khẩu',value:o.totalCitizens,unit:'người',icon:'fa-users',tone:'blue'},
{key:'male',label:'Nam',value:o.male,unit:'người',icon:'fa-mars',tone:'cyan'},
{key:'female',label:'Nữ',value:o.female,unit:'người',icon:'fa-venus',tone:'pink'},
{key:'elderly',label:'Người cao tuổi',value:o.elderly,unit:'người',icon:'fa-person-cane',tone:'purple'},
{key:'students',label:'Học sinh',value:o.students,unit:'người',icon:'fa-graduation-cap',tone:'blue'},
{key:'workingAge',label:'Lao động',value:o.workingAge,unit:'người',icon:'fa-briefcase',tone:'green'},
{key:'eligibleHealthInsurance',label:'Đủ điều kiện BHYT',value:p.eligibleHealthInsurance,unit:'người',icon:'fa-notes-medical',tone:'green'},
{key:'eligibleSocialSupport',label:'Đủ điều kiện bảo trợ',value:p.eligibleSocialSupport,unit:'người',icon:'fa-hand-holding-heart',tone:'orange'},
{key:'warningCount',label:'Cảnh báo cần xử lý',value:k.warningCount,unit:'việc',icon:'fa-triangle-exclamation',tone:k.warningCount?'orange':'green'}
];}
function executiveChart(source,labels){const data=source||{};return Object.keys(labels).map(key=>({label:labels[key],value:data[key]||0}));}
function renderExecutiveCommand(data){const screen=q('#dashboardScreen'),kpi=q('#dashboardKpis');if(!screen||!kpi)return;let host=q('#executiveCommandPanel',screen);if(!host){host=document.createElement('section');host.id='executiveCommandPanel';host.className='executive-command-grid';kpi.insertAdjacentElement('afterend',host);}const warnings=(data.warnings?.items||[]).slice(0,6);const bySeverity=data.warnings?.summary?.bySeverity||{};host.innerHTML='<article class="dashboard-panel executive-command-main"><div class="dashboard-panel-head"><h3>Công việc cần xử lý hôm nay</h3><span class="dashboard-filter-pill">'+fmt(data.kpi?.warningCount||0)+' việc</span></div>'+(warnings.length?'<div class="executive-warning-list">'+warnings.map(w=>'<button type="button" class="executive-warning-item" data-warning-code="'+esc(w.code||'')+'"><span class="executive-warning-severity executive-warning-'+esc(w.severity||'low')+'">'+esc(severityLabel(w.severity))+'</span><strong>'+esc(w.title||'Cảnh báo')+'</strong><small>'+esc(w.message||'')+'</small><em>'+esc(w.action?.label||'Kiểm tra và cập nhật dữ liệu')+'</em></button>').join('')+'</div>':'<div class="dashboard-empty-chart">Không có cảnh báo ưu tiên.</div>')+'</article><article class="dashboard-panel executive-command-side"><div class="dashboard-panel-head"><h3>Tình trạng điều hành</h3></div><div class="dashboard-metric-stack"><div class="dashboard-metric-line"><span>Cảnh báo cao</span><strong>'+fmt(bySeverity.high||0)+'</strong></div><div class="dashboard-metric-line"><span>Cảnh báo trung bình</span><strong>'+fmt(bySeverity.medium||0)+'</strong></div><div class="dashboard-metric-line"><span>Tỷ lệ BHYT</span><strong>'+fmt(data.kpi?.healthInsuranceRate||0)+'%</strong></div><div class="dashboard-metric-line"><span>Tỷ lệ dữ liệu cập nhật</span><strong>'+fmt(data.kpi?.dataUpdateRate||0)+'%</strong></div></div></article>';enhanceExecutiveWarnings(host);}
function severityLabel(value){return value==='high'?'Ưu tiên cao':value==='medium'?'Cần rà soát':'Theo dõi';}
function enhanceExecutiveWarnings(host){qa('.executive-warning-item[data-warning-code]',host).forEach(item=>{const code=String(item.dataset.warningCode||'').trim();if(!code)return;const ref='risk_warning:'+code;let actions=item.nextElementSibling;if(!actions||!actions.classList.contains('executive-warning-actions')){actions=document.createElement('div');actions.className='executive-warning-actions';item.insertAdjacentElement('afterend',actions);}renderExecutiveWarningActions(actions,ref,null);hydrateExecutiveWarningTask(actions,ref);});}
function renderExecutiveWarningActions(host,ref,task){if(task&&task.id){host.innerHTML='<span class="badge bg-success">Đã tạo công việc</span><button class="btn btn-sm btn-success" type="button" data-platform-action="moduleDashboard.openWorkTask" data-source-ref="'+esc(ref)+'">Mở công việc</button>';}else{host.innerHTML='<button class="btn btn-sm btn-outline-success" type="button" data-platform-action="moduleDashboard.createWorkTask" data-source-ref="'+esc(ref)+'"><i class="fa-solid fa-list-check"></i> Tạo công việc</button>';}}
async function hydrateExecutiveWarningTask(host,ref){if(!window.WorkTaskQuickCreate?.findBySource)return;try{renderExecutiveWarningActions(host,ref,await window.WorkTaskQuickCreate.findBySource(ref));}catch(_){}}
function createWorkTaskFromExecutiveWarning(item,ref){if(!item)return;const title=item.querySelector('strong')?.textContent||'Cảnh báo cần xử lý';window.WorkTaskQuickCreate?.open({sourceType:'Risk Warning',sourceId:String(ref||'').replace(/^risk_warning:/,''),sourceModule:'executive_dashboard',sourceTitle:title,sourceRef:ref,sourceUrl:'/dashboard',relatedModule:'risk_warning',title,description:item.querySelector('small')?.textContent||'',priority:item.querySelector('.executive-warning-high')?'high':(item.querySelector('.executive-warning-medium')?'medium':'low'),action:item.querySelector('em')?.textContent||'Kiểm tra và cập nhật dữ liệu',categoryCode:'other'});}
function renderKpis(sel,kpis){const host=q(sel);if(!host)return;host.innerHTML=(kpis||[]).map(c=>'<article class="dashboard-kpi dashboard-tone-'+esc(c.tone||'green')+'" data-kpi-label="'+esc(c.label||'')+'" data-kpi-value="'+esc(c.value||0)+'" data-kpi-unit="'+esc(c.unit||'')+'"><div class="dashboard-kpi-head"><span class="dashboard-kpi-icon"><i class="fa-solid '+esc(c.icon||'fa-chart-simple')+'"></i></span><span class="dashboard-kpi-label">'+esc(c.label)+'</span></div><div class="dashboard-kpi-value"><strong>'+fmt(c.value)+'</strong><span class="dashboard-kpi-unit">'+esc(c.unit||'')+'</span></div></article>').join('')||empty();}
function stamp(sel,value){const el=q(sel);if(!el)return;const d=value?new Date(value):new Date();el.textContent='Cập nhật lúc '+new Intl.DateTimeFormat('vi-VN',{hour:'2-digit',minute:'2-digit',day:'2-digit',month:'2-digit',year:'numeric'}).format(d);}
function chart(sel,items){const host=q(sel);if(!host)return;const total=(items||[]).reduce((s,i)=>s+Number(i.value||0),0);if(!total){host.innerHTML=empty();return;}if(typeof renderChart==='function'){renderChart(sel,items);return;}host.innerHTML='<div class="chart-list">'+items.map(i=>'<div class="chart-line"><span>'+esc(i.label)+'</span><div class="chart-track"><div class="chart-bar" style="width:'+Math.max(4,Math.round(Number(i.value||0)*100/total))+'%"></div></div><strong>'+fmt(i.value)+'</strong></div>').join('')+'</div>';}
function extra(sel,data){if(data.top&&data.top.length)return top(sel,data.top);if(data.layers)return layers(sel,data.layers);if(data.reports)return list(sel,data.reports);return list(sel,[]);}
function top(sel,rows){const host=q(sel);if(!host)return;const livestock=rows&&rows[0]&&Object.prototype.hasOwnProperty.call(rows[0],'livestock_total');const head=livestock?'<th>M\u00e3 h\u1ed9</th><th>Ch\u1ee7 h\u1ed9</th><th>Lo\u1ea1i</th><th>V\u1eadt nu\u00f4i</th>':'<th>M\u00e3 h\u1ed9</th><th>Ch\u1ee7 h\u1ed9</th><th>Ho\u1ea1t \u0111\u1ed9ng</th><th>Lao \u0111\u1ed9ng</th>';host.innerHTML='<div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr>'+head+'</tr></thead><tbody>'+rows.map(r=>'<tr><td>'+esc(r.household_code)+'</td><td>'+esc(r.head_citizen_name)+'</td><td>'+fmt(livestock?r.livestock_types:r.activity_count)+'</td><td>'+fmt(livestock?r.livestock_total:r.worker_count)+'</td></tr>').join('')+'</tbody></table></div>';}
function layers(sel,items){const host=q(sel);if(!host)return;host.innerHTML='<div class="d-grid gap-2">'+(items||[]).map((x,i)=>'<label class="form-check d-flex align-items-center gap-2"><input class="form-check-input" type="checkbox" checked data-dashboard-layer="'+i+'"><span>'+esc(x)+'</span></label>').join('')+'</div>';}
function list(sel,items){const host=q(sel);if(!host)return;if(!items||!items.length){host.innerHTML=empty();return;}host.innerHTML='<div class="dashboard-metric-stack">'+items.map(x=>'<div class="dashboard-metric-line"><span>'+esc(typeof x==='string'?x:x.label)+'</span><strong>'+(typeof x==='string'?'':esc(fmt(x.value||0)))+'</strong></div>').join('')+'</div>';}
function renderError(cfg,e){const host=q(cfg.kpis);if(host)host.innerHTML='<div class="alert alert-danger mb-0">'+esc(e.message||'Không tải được Dashboard')+'</div>';}
function currentScreen(){return window.TenantAppPlatform?.navigation?.current?.()?.screenId||window.App?.screen||document.querySelector('.screen.active')?.id?.replace(/Screen$/,'')||'dashboard';}
function screenFromTarget(target){return target?.closest?.('.screen')?.id?.replace(/Screen$/,'')||currentScreen();}
function registerDashboardActions(){const actions=window.TenantAppPlatform&&window.TenantAppPlatform.actions;if(!actions||typeof actions.register!=='function')return;actions.register('moduleDashboard.refresh',ctx=>load(screenFromTarget(ctx.target),true));actions.register('moduleDashboard.clear',ctx=>{const host=ctx.target?.closest?.('.screen');qa('[data-dashboard-filter]',host||document).forEach(el=>el.value='');return load(screenFromTarget(ctx.target),true);});actions.register('moduleDashboard.createWorkTask',ctx=>createWorkTaskFromExecutiveWarning(ctx.target?.closest?.('.executive-warning-actions')?.previousElementSibling,ctx.dataset.sourceRef||''));actions.register('moduleDashboard.openWorkTask',ctx=>window.WorkTaskQuickCreate?.openTaskBySource(ctx.dataset.sourceRef||''));}
function bind(screen){const host=q('#'+screen+'Screen');if(!host||host.dataset.dashboardBound==='1')return;host.dataset.dashboardBound='1';qa('[data-dashboard-filter]',host).forEach(el=>el.addEventListener('change',()=>load(screen,true)));}
function activate(screen){if(configs[screen])load(screen,false);}
document.addEventListener('tenant:screen-change',e=>activate(e.detail?.screen));
document.addEventListener('work-tasks:changed',()=>{if(currentScreen()==='dashboard')load('dashboard',true);});
document.addEventListener('DOMContentLoaded',()=>{registerDashboardActions();const active=q('.screen.active');if(active)activate(active.id.replace(/Screen$/,''));});
window.loadModuleDashboard=(screen,force)=>load(screen||currentScreen(),!!force);
})();
